2\\u0430\\u0442\\u043e\\u0447\\u043d\\u0430 \\u0434\\u043b\\u044f \\u0441\\u0445\\u043e\\u0434\\u0438\\u043c\\u043e\\u0441\\u0442\\u0438 ACF \\u0438 PSD (\\u226510\\u00d7 \\u043c\\u0430\\u043a\\u0441\\u0438\\u043c\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u03c4 \\u0438 \\u226510 \\u043f\\u0435\\u0440\\u0438\\u043e\\u0434\\u043e\\u0432 \\u043c\\u0438\\u0448\\u0435\\u043d\\u0438).\", \"A6: JS/KL \\u043d\\u0430 \\u0442\\u043e\\u0440\\u0441\\u0438\\u044f\\u0445 \\u0441 wrap-around \\u0438 \\u0431\\u0438\\u043d\\u043d\\u0438\\u043d\\u0433\\u043e\\u043c \\u226536 \\u0431\\u0438\\u043d\\u043e\\u0432 \\u2014 \\u0430\\u0434\\u0435\\u043a\\u0432\\u0430\\u0442\\u043d\\u044b\\u0435 \\u043c\\u0435\\u0442\\u0440\\u0438\\u043a\\u0438 \\u043a\\u0430\\u0447\\u0435\\u0441\\u0442\\u0432\\u0430 \\u0440\\u0435\\u043a\\u043e\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u0438.\", \"A7: \\u00ab\\u0432\\u043e\\u0441\\u0441\\u0442\\u0430\\u043d\\u043e\\u0432\\u0438\\u043b\\u00bb = (i) JS-Ramachandran \\u2264 T_js, (ii) \\u0434\\u043e\\u043c\\u0438\\u043d\\u0430\\u043d\\u0442\\u043d\\u044b\\u0435 \\u0447\\u0430\\u0441\\u0442\\u043e\\u0442\\u044b PSD \\u0432 \\u043f\\u043e\\u043b\\u043e\\u0441\\u0435 \\u00b1\\u0394f, (iii) \\u0432\\u0440\\u0435\\u043c\\u0435\\u043d\\u0430 \\u043a\\u043e\\u0440\\u0440\\u0435\\u043b\\u044f\\u0446\\u0438\\u0438 \\u0432 \\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u0430\\u0445 \\u03b5\\u00b7\\u03c4_ref; \\u043a\\u043e\\u043d\\u043a\\u0440\\u0435\\u0442\\u043d\\u044b\\u0435 T_js/\\u0394f/\\u03b5 \\u2014 \\u043d\\u0430 \\u0432\\u044b\\u0431\\u043e\\u0440 \\u0438\\u0441\\u0441\\u043b\\u0435\\u0434\\u043e\\u0432\\u0430\\u0442\\u0435\\u043b\\u044f.\"], \"uncertainties\": [\"Q1: \\u043a\\u0430\\u043a\\u043e\\u0439 \\u0438\\u043c\\u0435\\u043d\\u043d\\u043e \\u0432\\u0430\\u0440\\u0438\\u0430\\u043d\\u0442 MDGEN (Bt-mask diffusion / \\u0438\\u043d\\u043e\\u0439 \\u0444\\u043e\\u0440\\u043a), \\u043a\\u0430\\u043a\\u043e\\u0439 backbone (E(3)-\\u0442\\