430\\u0436\\u0434\\u044b\\u0439 `(\\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u0430, S, \\u0441\\u0446\\u0435\\u043d\\u0430\\u0440\\u0438\\u0439, \\u043c\\u043e\\u0434\\u0435\\u043b\\u044c)`. \\u0424\\u0438\\u043a\\u0441\\u0438\\u0440\\u0443\\u0435\\u0442\\u0441\\u044f \\u0442\\u043e\\u0447\\u043d\\u043e\\u0435 `torch.Generator` \\u0441\\u043e\\u0441\\u0442\\u043e\\u044f\\u043d\\u0438\\u0435 (\\u0438\\u043b\\u0438 \\u0430\\u043d\\u0430\\u043b\\u043e\\u0433 \\u0432 JAX).\\n\\n**C2. Window-\\u043d\\u043e\\u0440\\u043c\\u0430\\u043b\\u0438\\u0437\\u0430\\u0446\\u0438\\u044f.** \\u041a\\u0430\\u0436\\u0434\\u0430\\u044f \\u043f\\u0430\\u0440\\u0430 \\u043e\\u043a\\u043e\\u043d \\u0441\\u0442\\u0430\\u0440\\u0442\\u0443\\u0435\\u0442 \\u0441 **\\u0440\\u0430\\u0437\\u043d\\u044b\\u0445 \\u043c\\u043e\\u043c\\u0435\\u043d\\u0442\\u043e\\u0432 \\u0438\\u0441\\u0445\\u043e\\u0434\\u043d\\u043e\\u0439 MD-\\u0442\\u0440\\u0430\\u0435\\u043a\\u0442\\u043e\\u0440\\u0438\\u0438** (`seed_window \\u2208 {1, \\u2026, N_windows}`, `N_windows \\u2265 5`). \\u042d\\u0442\\u043e \\u0443\\u0431\\u0438\\u0440\\u0430\\u0435\\u0442 \\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u0430\\u0442\\u0438\\u043a\\u0443 \\u043e\\u0442 \\u0430\\u0440\\u0442\\u0435\\u0444\\u0430\\u043a\\u0442\\u043e\\u0432 \\u043d\\u0430\\u0447\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u043e\\u043a\\u043d\\u0430.\\n\\n**C3. Drift-check.** \\u0414\\u043b\\u044f \\u043a\\u0430\\u0436\\u0434\\u043e\\u0439 \\u0432\\u043e\\u0441\\u0441\\u0442\\u0430\\u043d\\u043e\\u0432\\u043b\\u0435\\u043d\\u043d\\u043e\\u0439 fs-\\u0442\\u0440\\u0430\\u0435\\u043a\\u0442\\u043e\\u0440\\u0438\\u0438 \\u0434\\u043b\\u0438\\u043d\\u044b > 1 \\u043d\\u0441 \\u2014 \\u0441\\u0440\\u0430\\u0432\\u043d\\u0438\\u0442\\u044c \\u0440\\u0430\\u0441\\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u0435\\u043d\\u0438\\u044f \\u0442\\u043e\\u0440\\u0441\\u0438\\u043e\\u043d\\u043e\\u0432 \\u043d\\u0430 \\u043f\\u0435\\u0440\\u0432\\u043e\\u0439 \\u0438 \\u0432\\u0442\\u043e\\u0440\\u043e\\u0439 \\u043f\\u043e\\u043b\\u043e\\u0432\\u0438\\u043d\\u0430\\u0445. \\u0394JS \\u043c\\u0435\\u0436\\u0434\\u0443 \\u043f\\u043e\\u043b\\u043e\\u0432\\u0438\\u043d\\u0430\\u043c\\u0438 \\u0434\\u043e\\u043b\\u0436\\u043d\\u043e \\u0431\\u044b\\u0442\\u044c \\u0432 \\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u0430\\u0445 bootstrap-CI.\\n\\n**C4. S-artifact sweep.** \\u0412\\u0441\\u0435 \\u043c\\u0435\\u0442\\u0440\\u0438\\u043a\\u0438 \\u043e\\u0442\\u0447\\u0438\\u0442\\u044b\\u0432\\u0430\\u044e\\u0442\\u0441\\u044f \\u043a\\u0430\\u043a \\u0444\\u0443\\u043d\\u043a\\u0446\\u0438\\u0438 S. \\u041e\\u0436\\u0438\\u0434\\u0430\\u0435\\u043c\\u0430\\u044f \\u043c\\u043e\\u043d\\u043e\\u0442\\u043e\\u043d\\u043d\\u043e\\u0441\\u0442\\u044c (\\u0445\\u0443\\u0434\\u0448\\u0435\\u0435 \\u0441 \\u0431\\u043e\\u0301\\u043b\\u044c\\u0448\\u0438\\u043c S) \\u2014 sanity-check.\\n\\n**C5. In-distribution vs OOD split.** \\u0417\\u0430\\u0440\\u0435\\u0437\\u0435\\u0440\\u0432\\u0438\\u0440\\u043e\\u0432\\u0430\\u0442\\u044c L3-OOD \\u043a\\u0430\\u043a \\u0437\\u0430\\u0432\\u0435\\u0434\\u043e\\u043c\\u043e OOD-\\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u0443, \\u043e\\u0442\\u0434\\u0435\\u043b\\u044c\\u043d\\u044b\\u0439 \\u0440\\u0435\\u043f\\u043e\\u0440\\u0442.\\n\\n**C6. \\u0414\\u0435\\u0442\\u0435\\u0440\\u043c\\u0438\\u043d\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u043e\\u0441\\u0442\\u044c conditioning.** \\u041e\\u0434\\u043d\\u0438 \\u0438 \\u0442\\u0435 \\u0436\\u0435 conditioning-\\u043a\\u0430\\u0434\\u0440\\u044b \\u043f\\u043e\\u0434\\u0430\\u044e\\u0442\\u0441\\u044f \\u0432\\u0441\\u0435\\u043c \\u043c\\u043e\\u0434\\u0435\\u043b\\u044f\\u043c \\u0438 \\u0431\\u0430\\u0437\\u0430\\u043c \\u0432 \\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u0430\\u0445 \\u043e\\u0434\\u043d\\u043e\\u0433\\u043e `(\\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u0430, S, scenario)` \\u2014 \\u0432\\u043a\\u043b\\u044e\\u0447\\u0435\\u043d\\u043e \\u0432 \\u0436\\u0443\\u0440\\u043d\\u0430\\u043b.\\n\\n**C7. \\u041a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u044c \\u044d\\u043d\\u0435\\u0440\\u0433\\u0438\\u0438 / \\u0430\\u0440\\u0442\\u0435\\u0444\\u0430\\u043a\\u0442\\u043e\\u0432 \\u0438\\u043d\\u0444\\u0435\\u0440\\u0435\\u043d\\u0441\\u0430.** (\\u0412\\u043d\\u0435 \\u0444\\u043e\\u0440\\u043c\\u0430\\u043b\\u044c\\u043d\\u044b\\u0445 \\u043c\\u0435\\u0442\\u0440\\u0438\\u043a, \\u0432 \\u043f\\u0440\\u0438\\u043b\\u043e\\u0436\\u0435\\u043d\\u0438\\u0438): \\u0441\\u044d\\u043c\\u043f\\u043b\\u0438\\u0440\\u0443\\u0435\\u043c \\u0438\\u0437 MDGEN \\u0432 \\u0448\\u0438\\u0440\\u043e\\u043a\\u043e\\u043c \\u00ab\\u0441\\u0432\\u043e\\u0431\\u043e\\u0434\\u043d\\u043e\\u043c\\u00bb \\u0440\\u0435\\u0436\\u0438\\u043c\\u0435 \\u0438 \\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u044f\\u0435\\u043c, \\u0447\\u0442\\u043e \\u043d\\u0435\\u0442 \\u043a\\u043e\\u043b\\u043b\\u0438\\u0437\\u0438\\u0439 \\u0430\\u0442\\u043e\\u043c\\u043e\\u0432 (steric clash statistic), \\u0447\\u0442\\u043e \\u043e\\u0442\\u043a\\u043b\\u043e\\u043d\\u0435\\u043d\\u0438\\u044f \\u043e\\u0442 conditioning \\u043c\\u0435\\u043d\\u044c\\u0448\\u0435 \\u0437\\u0430\\u0434\\u0430\\u043d\\u043d\\u043e\\u0433\\u043e tolerance.\\n\\n---\\n\\n## (f) \\u041f\\u043b\\u0430\\u043d \\u0441\\u0442\\u0430\\u0442\\u0438\\u0441\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0433\\u043e \\u0430\\u043d\\u0430\\u043b\\u0438\\u0437\\u0430\\n\\n### f.1 \\u0423\\u0440\\u043e\\u0432\\u043d\\u0438 \\u0430\\u0433\\u0440\\u0435\\u0433\\u0430\\u0446\\u0438\\u0438\\n\\n- **Level 0** (\\u043c\\u0438\\u043d\\u0438\\u043c\\u0430\\u043b\\u044c\\u043d\\u044b\\u0439): \\u043e\\u0434\\u0438\\u043d \\u0441\\u043a\\u0430\\u043b\\u044f\\u0440 \\u043d\\u0430 `(\\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u0430, S, \\u0441\\u0446\\u0435\\u043d\\u0430\\u0440\\u0438\\u0439, \\u043c\\u043e\\u0434\\u0435\\u043b\\u044c, \\u043c\\u0435\\u0442\\u0440\\u0438\\u043a\\u0430, \\u043e\\u0441\\u0442\\u0430\\u0442\\u043e\\u043a-\\u0438\\u043b\\u0438-\\u0442\\u0438\\u043f-\\u0410\\u041a\\u041e, \\u0442\\u043e\\u0440\\u0441\\u0438\\u044f)`.\\n- **Level 1**: \\u0430\\u0433\\u0440\\u0435\\u0433\\u0430\\u0446\\u0438\\u044f \\u043f\\u043e \\u0442\\u043e\\u0440\\u0441\\u0438\\u0438 \\u0432 \\u043e\\u0441\\u0442\\u0430\\u0442\\u043a\\u0435 / \\u043f\\u043e \\u0442\\u0438\\u043f\\u0443 \\u0410\\u041a\\u041e \\u043f\\u043e \\u0441\\u0435\\u043c\\u0435\\u043d\\u0438.\\n- **Level 2**: \\u0430\\u0433\\u0440\\u0435\\u0433\\u0430\\u0446\\u0438\\u044f \\u043f\\u043e \\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u0435 \\u00d7 S; \\u0438 \\u043f\\u043e \\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u0435 \\u00d7 S \\u00d7 \\u0441\\u0446\\u0435\\u043d\\u0430\\u0440\\u0438\\u0439.\\n- **Level 3**: \\u0433\\u043b\\u043e\\u0431\\u0430\\u043b\\u044c\\u043d\\u044b\\u0439 \\u2014 \\u043f\\u043e \\u0432\\u0441\\u0435\\u043c \\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u0430\\u043c.\\n\\n### f.2 \\u0421\\u0442\\u0430\\u0442\\u0438\\u0441\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0435 \\u0442\\u0435\\u0441\\u0442\\u044b\\n\\n- **Bootstrap** (10 000 \\u0440\\u0435\\u0441\\u044d\\u043c\\u043f\\u043b\\u043e\\u0432): \\u043f\\u043e \\u043f\\u0430\\u0440\\u0430\\u043c `(seed_window, seed_inference)`. \\u041c\\u0435\\u0442\\u043e\\u0434: percentile bootstrap \\u0434\\u043b\\u044f \\u043c\\u0435\\u0434\\u0438\\u0430\\u043d \\u0438 \\u0441\\u0440\\u0435\\u0434\\u043d\\u0438\\u0445; bias-corrected and accelerated (BCa) \\u0434\\u043b\\u044f ratio-\\u043c\\u0435\\u0442\\u0440\\u0438\\u043a (\\u043d\\u0430\\u043f\\u0440\\u0438\\u043c\\u0435\\u0440, error_MDGEN / error_B3).\\n- **\\u041f\\u0435\\u0440\\u0435\\u0441\\u0442\\u0430\\u043d\\u043e\\u0432\\u043e\\u0447\\u043d\\u044b\\u0439 \\u0442\\u0435\\u0441\\u0442**: 10 000 \\u043f\\u0435\\u0440\\u0435\\u043c\\u0435\\u0448\\u0438\\u0432\\u0430\\u043d\\u0438\\u0439 \\u0434\\u043b\\u044f \\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u043a\\u0438 \\u043f\\u0430\\u0440\\u043d\\u044b\\u0445 \\u0433\\u0438\\u043f\\u043e\\u0442\\u0435\\u0437 MDGEN vs B3 vs B4 \\u043d\\u0430 \\u043a\\u0430\\u0436\\u0434\\u043e\\u0439 \\u043f\\u043e\\u043b\\u043e\\u0441\\u0435 \\u0443\\u0441\\u043b\\u043e\\u0432\\u0438\\u0439. \\u041e\\u0434\\u043d\\u043e\\u0441\\u0442\\u043e\\u0440\\u043e\\u043d\\u043d\\u0438\\u0439 \\u043f\\u0440\\u0438 H1.\\n- **\\u0421\\u043c\\u0435\\u0448\\u0430\\u043d\\u043d\\u0430\\u044f \\u043c\\u043e\\u0434\\u0435\\u043b\\u044c (sensitivity, \\u043d\\u0435 primary)**: \\u0434\\u043b\\u044f \\u043a\\u0430\\u0436\\u0434\\u043e\\u0439 \\u043c\\u0435\\u0442\\u0440\\u0438\\u043a\\u0438 `Y_{r,sys,S,seed} = \\u03b2_model \\u00b7 Family(model) + u_sys + u_residue + \\u03b5`, \\u0433\\u0434\\u0435 `u_*` \\u2014 \\u0441\\u043b\\u0443\\u0447\\u0430\\u0439\\u043d\\u044b\\u0435 \\u044d\\u0444\\u0444\\u0435\\u043a\\u0442\\u044b. \\u041f\\u0440\\u043e\\u0432\\u0435\\u0440\\u044f\\u0435\\u0442\\u0441\\u044f, \\u043d\\u0435 \\u0440\\u0430\\u0437\\u043c\\u044b\\u0432\\u0430\\u0435\\u0442\\u0441\\u044f \\u043b\\u0438 \\u0441\\u0438\\u0433\\u043d\\u0430\\u043b \\u043d\\u0435\\u043d\\u0443\\u043b\\u0435\\u0432\\u043e\\u0439 \\u03b2_model \\u043f\\u0440\\u0438 \\u0432\\u043a\\u043b\\u044e\\u0447\\u0435\\u043d\\u0438\\u0438 \\u0438\\u0435\\u0440\\u0430\\u0440\\u0445\\u0438\\u0438.\\n- **\\u041a\\u043e\\u0440\\u0440\\u0435\\u043a\\u0446\\u0438\\u044f \\u043c\\u043d\\u043e\\u0436\\u0435\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u044b\\u0445 \\u0441\\u0440\\u0430\\u0432\\u043d\\u0435\\u043d\\u0438\\u0439**: Benjamini\\u2013Hochberg (FDR = 0.05) \\u043f\\u043e \\u0432\\u0441\\u0435\\u043c \\u044f\\u0447\\u0435\\u0439\\u043a\\u0430\\u043c `(\\u043c\\u0435\\u0442\\u0440\\u0438\\u043a\\u0430 \\u00d7 \\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u0430 \\u00d7 S \\u00d7 \\u0441\\u0446\\u0435\\u043d\\u0430\\u0440\\u0438\\u0439 \\u00d7 \\u0431\\u0430\\u0437\\u0430)` \\u0432\\u043d\\u0443\\u0442\\u0440\\u0438 \\u043e\\u0434\\u043d\\u043e\\u0433\\u043e \\u043e\\u0442\\u0447\\u0451\\u0442\\u0430, \\u043e\\u0442\\u0434\\u0435\\u043b\\u044c\\u043d\\u043e \\u0434\\u043b\\u044f \\u0441\\u0442\\u0430\\u0442\\u0438\\u043a\\u0438 \\u0438 \\u0434\\u0438\\u043d\\u0430\\u043c\\u0438\\u043a\\u0438 (\\u0441\\u043c. R10: \\u043f\\u0443\\u0442\\u0430\\u0442\\u044c \\u0441\\u0442\\u0430\\u0442\\u0438\\u043a\\u0443 \\u0438 \\u0434\\u0438\\u043d\\u0430\\u043c\\u0438\\u043a\\u0443 \\u0432 \\u043e\\u0434\\u043d\\u043e\\u0439 \\u043a\\u043e\\u0440\\u0440\\u0435\\u043a\\u0446\\u0438\\u0438 \\u043d\\u0435\\u043b\\u044c\\u0437\\u044f, \\u043f\\u043e\\u0441\\u043a\\u043e\\u043b\\u044c\\u043a\\u0443 \\u0437\\u0430\\u0432\\u0438\\u0441\\u0438\\u043c\\u043e\\u0441\\u0442\\u0438 \\u0440\\u0430\\u0437\\u043d\\u044b\\u0435).\\n\\n### f.3 \\u0424\\u043e\\u0440\\u043c\\u0430\\u0442 \\u043e\\u0442\\u0447\\u0451\\u0442\\u043d\\u043e\\u0441\\u0442\\u0438 (\\u0430\\u0440\\u0442\\u0435\\u0444\\u0430\\u043a\\u0442\\u044b)\\n\\n- **\\u0422\\u0430\\u0431\\u043b\\u0438\\u0446\\u0430 T1 (\\u0441\\u0442\\u0430\\u0442\\u0438\\u043a\\u0430)**: \\u0441\\u0442\\u0440\\u043e\\u043a\\u0438 \\u2014 `(system \\u00d7 S \\u00d7 scenario \\u00d7 torsion-class)`; \\u0441\\u0442\\u043e\\u043b\\u0431\\u0446\\u044b \\u2014 `model` \\u2192 `[median, 95% CI, dec_pass_vs_B3 (\\u0434\\u0430/\\u043d\\u0435\\u0442/\\u043d\\u0435\\u043e\\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u0451\\u043d\\u043d\\u043e)]`.\\n- **\\u0422\\u0430\\u0431\\u043b\\u0438\\u0446\\u0430 T2 (\\u0434\\u0438\\u043d\\u0430\\u043c\\u0438\\u043a\\u0430)**: \\u0442\\u043e \\u0436\\u0435, \\u043d\\u043e \\u043f\\u043e `\\u03c4_int`, `dominant_freq_band`, `KL_transition`.\\n- **\\u0422\\u0430\\u0431\\u043b\\u0438\\u0446\\u0430 T3 (decision matrix)**: \\u043e\\u0434\\u043d\\u0430 \\u0441\\u0442\\u0440\\u043e\\u043a\\u0430 \\u043d\\u0430 \\u043a\\u0430\\u0436\\u0434\\u044b\\u0439 `(system \\u00d7 S)`, \\u043a\\u043e\\u043b\\u043e\\u043d\\u043a\\u0438: H1 \\u043f\\u043e \\u0441\\u0442\\u0430\\u0442\\u0438\\u043a\\u0435, H1 \\u043f\\u043e \\u0434\\u0438\\u043d\\u0430\\u043c\\u0438\\u043a\\u0435, Hweak vs Hnull \\u0441 \\u0443\\u043a\\u0430\\u0437\\u0430\\u043d\\u0438\\u0435\\u043c \\u0437\\u043d\\u0430\\u043a\\u0430 \\u0438 p-value.\\n- **\\u0420\\u0438\\u0441\\u0443\\u043d\\u043e\\u043a F1**: 4\\u00d7N \\u043a\\u043e\\u043b\\u043e\\u043d\\u043e\\u043a \\u2014 \\u044d\\u0442\\u0430\\u043b\\u043e\\u043d / B3 / MDGEN / (B5 genie) \\u2014 \\u0420\\u0430\\u043c\\u0430\\u0447\\u0430\\u043d\\u0434\\u0440\\u0430\\u043d \\u0434\\u043b\\u044f \\u0432\\u044b\\u0431\\u0440\\u0430\\u043d\\u043d\\u044b\\u0445 \\u043e\\u0441\\u0442\\u0430\\u0442\\u043a\\u043e\\u0432.\\n- **\\u0420\\u0438\\u0441\\u0443\\u043d\\u043e\\u043a F2**: ACF-\\u043d\\u0430\\u043b\\u043e\\u0436\\u0435\\u043d\\u0438\\u0435 \\u0434\\u043b\\u044f MDGEN vs B3 vs \\u044d\\u0442\\u0430\\u043b\\u043e\\u043d, \\u0434\\u043b\\u044f \\u043a\\u0430\\u0436\\u0434\\u043e\\u0433\\u043e `(system \\u00d7 S \\u00d7 residue-class)`.\\n- **\\u0420\\u0438\\u0441\\u0443\\u043d\\u043e\\u043a F3**: \\u0441\\u0442\\u043e\\u043b\\u0431\\u0447\\u0430\\u0442\\u0430\\u044f \\u0434\\u0438\\u0430\\u0433\\u0440\\u0430\\u043c\\u043c\\u0430 \\u043c\\u043e\\u0449\\u043d\\u043e\\u0441\\u0442\\u0438 PSD \\u043f\\u043e \\u043f\\u043e\\u043b\\u043e\\u0441\\u0430\\u043c \\u0441 error-bars.\\n- **\\u0420\\u0438\\u0441\\u0443\\u043d\\u043e\\u043a F4 (\\u0433\\u043b\\u0430\\u0432\\u043d\\u044b\\u0439 \\u0438\\u0442\\u043e\\u0433)**: heatmap \\u00ab\\u0443\\u0441\\u043f\\u0435\\u0432\\u0430\\u0435\\u043c\\u043e\\u0441\\u0442\\u0438\\u00bb \\u2014 \\u0441\\u0442\\u0440\\u043e\\u043a\\u0438 `(system \\u00d7 S)`, \\u0441\\u0442\\u043e\\u043b\\u0431\\u0446\\u044b \\u2014 `(metric, test)`; \\u0446\\u0432\\u0435\\u0442 = pass/neutral/fail \\u0441 \\u0441\\u0438\\u043c\\u0432\\u043e\\u043b\\u0430\\u043c\\u0438 bootstrap-CI.\\n\\n### f.4 \\u041a\\u0440\\u0438\\u0442\\u0435\\u0440\\u0438\\u0438 \\u00ab\\u0432\\u043e\